import pandas as pd
import json
import ast

def process_coordinates(coord):
    """
    Convert the 'coordinates' field to string.
    If it's a dict (JSON-like), convert to JSON string.
    If NaN or other, convert to string 'nan' or keep as is.
    """
    if pd.isna(coord):
        return 'nan'
    if isinstance(coord, dict):
        return json.dumps(coord)
    # Sometimes coordinates might be string representations of dicts
    if isinstance(coord, str):
        coord = coord.strip()
        if coord == 'nan' or coord == '':
            return 'nan'
        try:
            # Try to parse string dict to dict and then json dump
            parsed = ast.literal_eval(coord)
            if isinstance(parsed, dict):
                return json.dumps(parsed)
            else:
                return coord
        except:
            return coord
    return str(coord)

def process_hashtags(hashtags):
    """
    Convert the 'hashtags' field to string representation of list of strings.
    Source hashtags can be:
    - empty list []
    - list of dicts [{'text': 'tag', 'indices': [...]}, ...]
    We want to convert to a string of list of hashtag texts, e.g. "['tag1', 'tag2']"
    If NaN or empty, return "[]"
    """
    if pd.isna(hashtags):
        return "[]"
    if isinstance(hashtags, list):
        # list of dicts or empty list
        texts = []
        for h in hashtags:
            if isinstance(h, dict) and 'text' in h:
                texts.append(h['text'])
            elif isinstance(h, str):
                texts.append(h)
        return str(texts)
    if isinstance(hashtags, str):
        hashtags = hashtags.strip()
        if hashtags == '' or hashtags.lower() == 'nan':
            return "[]"
        try:
            # Try to parse string representation of list
            parsed = ast.literal_eval(hashtags)
            if isinstance(parsed, list):
                texts = []
                for h in parsed:
                    if isinstance(h, dict) and 'text' in h:
                        texts.append(h['text'])
                    elif isinstance(h, str):
                        texts.append(h)
                return str(texts)
            else:
                return "[]"
        except:
            # If cannot parse, return as is inside list
            return str([hashtags])
    return "[]"

def main():
    # List all source file paths
    source_files = [
        "autopipeline-benchmarks/github-pipelines/length6_62/training_0.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_1.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_2.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_3.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_4.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_5.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_6.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_7.csv",
        "autopipeline-benchmarks/github-pipelines/length6_62/training_8.csv"
    ]

    dfs = []
    for file_path in source_files:
        # Read CSV with index_col=0 to ignore the first numerical index column
        df = pd.read_csv(file_path, index_col=0)

        # Ensure columns are exactly ['created_at', 'text', 'coordinates', 'hashtags']
        # If any extra columns, drop them
        df = df[['created_at', 'text', 'coordinates', 'hashtags']]

        # Process 'coordinates' column to string
        df['coordinates'] = df['coordinates'].apply(process_coordinates)

        # Process 'hashtags' column to string list of hashtag texts
        df['hashtags'] = df['hashtags'].apply(process_hashtags)

        # Convert 'created_at' to string (in case it's datetime or other)
        df['created_at'] = df['created_at'].astype(str)

        # Convert 'text' to string (in case of any non-string)
        df['text'] = df['text'].astype(str)

        dfs.append(df)

    # Since all source tables have the same schema as target, union (concat) them
    target_df = pd.concat(dfs, ignore_index=True)

    # Save to the target CSV file without the index column
    target_df.to_csv("autopipeline-benchmarks/github-pipelines/length6_62/target_multisource_cot.csv", index=False)

if __name__ == "__main__":
    main()
